const Items = `-- name: Items :many
SELECT id, delivery_run_id, item_kind, item_key, user_id, article_id, status, legacy_status,
     owner_id, lease_expires_at, attempt_count, result_json, error_code, revision,
     created_at, started_at, updated_at, finished_at FROM delivery_run_items WHERE delivery_run_id=? ORDER BY id
`

type ItemsParams struct {
	DeliveryRunID sqlite.Integer
}

func (q *Queries) Items(ctx context.Context, db DBTX, arg ItemsParams) ([]DeliveryRunItem, error) {
	rows, err := db.QueryContext(ctx, Items, arg.DeliveryRunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DeliveryRunItem{}
	for rows.Next() {
		var i DeliveryRunItem
		if err := rows.Scan(
			&i.ID,
			&i.DeliveryRunID,
			&i.ItemKind,
			&i.ItemKey,
			&i.UserID,
			&i.ArticleID,
			&i.Status,
			&i.LegacyStatus,
			&i.OwnerID,
			&i.LeaseExpiresAt,
			&i.AttemptCount,
			&i.ResultJSON,
			&i.ErrorCode,
			&i.Revision,
			&i.CreatedAt,
			&i.StartedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

